"""
Claudcodellm Trading - v5-BIRLESIK (TEK DOSYA; Pydroid/PC)
==========================================================
Icerik: v4 kaynagi GOMULU (md5 dogrulamali) + v5 katmanlari:
  - I13 : f*=0 iken yon satiri BILGI'ye doner; manset 'HUKUM: BAHIS YOK'
  - I17 : FADE bahis sinifi (+/-2.0xATR cift limit, 1.5xATR hedef,
          1.0xATR stop, R=1.5) + fail-closed stake kapisu
          (n<30 veya edge<=0 -> 'HUKUM_FADE: BAHIS YOK', stake 0)
  - OKX uyum katmani: getir katmaninda sema cevirimi + ic sayfalama
  - P2  : v4 kaynak-tarama yardimcisi gomulu kaynaga yonlendirilir
          (bellek-ici; taranan metin CALISAN kaynak - v5'tekinden kati)
  - R1  : OKX public hiz sinirina dayaniklilik: istekler arasi >=0.12 s
          + 429/5xx/gecici ag hatasi geri cekilmesi (0.6/1.8/4.5/9.0 s)
Diskte Claudcodellm_trading_v4.py GEREKMEZ - v4 bu dosyanin icinde.
Not: --self-test mumkunse canli BTC 2H verisiyle T2/T7/T9'i da calistirir
(ag yoksa bu uc test atlanir; diger 14'u bagimsiz calisir).

KULLANIM (tek basina calistirin):
  python Claudcodellm_trading_v5_birlesik.py             # tam kosu
  python Claudcodellm_trading_v5_birlesik.py --fade-only # FADE durum tablosu
  python Claudcodellm_trading_v5_birlesik.py --self-test # 17 test

GUVENLIK: yalnizca OKX PUBLIC GET uclari; API anahtari/imza/emir YOK.
Karar-destek sistemidir; yatirim tavsiyesi degildir. Canli veri icin
internet gerekir; 24 saat taze onbellek varsa otomatik kullanilir.
"""
from __future__ import annotations

import importlib.util
import json
import os
import sys
import time

