def _v4_yukle():
    kaynak_ham = _b64.b64decode(V4_B64).decode("utf-8")
    if (len(kaynak_ham) != V4_LEN
            or _hl.md5(kaynak_ham.encode("utf-8")).hexdigest()
            != V4_MD5):
        raise RuntimeError("GOMULU v4 BOZUK (md5/uzunluk uyusmadi): "
                           "dosyayi yeniden indirin; sessiz calisma YOK")
    kaynak, i13 = _i13_uygula(kaynak_ham)
    mod = _tp.ModuleType("tv4_v5")
    sys.modules["tv4_v5"] = mod
    mod.__dict__["__name__"] = "tv4_v5"
    mod.__dict__["__file__"] = "<gomulu_v4>"
    exec(compile(kaynak, "<gomulu_v4>", "exec"), mod.__dict__)
    if "_modul_kaynagi" in mod.__dict__ and "_TEST_BOLUMU_SINIRI" in mod.__dict__:
        _sinir = mod.__dict__["_TEST_BOLUMU_SINIRI"]

        def _gomulu_kaynak_taramasi(_kaynak=kaynak, _sinir=_sinir):
            k = _kaynak.find(_sinir)
            return _kaynak if k < 0 else _kaynak[:k]
        mod.__dict__["_modul_kaynagi"] = _gomulu_kaynak_taramasi
    return mod, i13


# ---- R1: OKX public hiz sinirina dayanikli cekim (v5-birlesik) ----
_SON_ISTEK = [0.0]


def _direncli_cek(url, params, zaman_asimi=20):
    """TV4.http_getir sarmasi: istekler arasi >= 0.12 s (hiz siniri) +
    429/5xx/gecici ag hatasinda geri cekilme (0.6/1.8/4.5/9.0 s).
    Yalniz varsayilan cek yolu; test sahte cek'leri etkilenmez."""
    import time as _tm
    import urllib.error as _ue
    for deneme, bekle in enumerate((0.6, 1.8, 4.5, 9.0)):
        gec = 0.12 - (_tm.time() - _SON_ISTEK[0])
        if gec > 0:
            _tm.sleep(gec)
        _SON_ISTEK[0] = _tm.time()
        try:
            return TV4.http_getir(url, params, zaman_asimi)
        except Exception as e:
            gecici = (isinstance(e, _ue.HTTPError)
                      and e.code in (429, 500, 502, 503, 504)) or (
                isinstance(e, _ue.URLError)
                and not isinstance(e, _ue.HTTPError))
            if not gecici or deneme >= 3:
                raise
            _tm.sleep(bekle)


TV4, I13_DURUM = _v4_yukle()

